package dev.studyforge.banking.adapter.inmemory; import dev.studyforge.banking.application.*; import dev.studyforge.banking.domain.*; import java.util.*; public final class InMemoryTransactionRepository implements TransactionRepository{private final List<Transaction> data=new ArrayList<>(); public void save(Transaction t){data.add(t);} public List<Transaction> findAll(){return List.copyOf(data);} List<Transaction> copy(){return new ArrayList<>(data);} void replace(List<Transaction> l){data.clear();data.addAll(l);}}
